import math

def compute_diff(M):
    t1 = 0
    curr_t1 = 1.0
    for n in range(1, M):
        curr_t1 *= M / (M + n)
        t1 += curr_t1

    t2 = 0
    curr_t2 = 1.0
    for n in range(1, M):
        curr_t2 *= (M - n) / M
        t2 += curr_t2

    return t1 - t2

results = []
for M in range(2, 200):
    results.append((M, compute_diff(M)))

for r in results:
    if r[1] > 0.66:
        print(r)
